m=json.loads((p/'material.json').read_text(encoding='utf-8')); i=json.loads(m['current_input_json']); r=json.loads((p/'issued-request.json').read_text(encoding='utf-8')); s=json.loads((p/'stage.json').read_text(encoding='utf-8')); a=json.loads(m['source_message'].split('\\n',1)[1].rsplit('\\n',1)[0])
for n,msg in enumerate(r['messages']):
 print('MESSAGE',n,{k:v for k,v in msg.items() if k"'!='"'content'})
 matches=[k for k in ('full_policy_text','source_message','deterministic_source_message') if msg['content']==m[k]]
 print('exact matches',matches)
 if not matches: print(msg['content'])
print('REQUEST REST',json.dumps({k:v for k,v in r.items() if k"'!='"'messages'},ensure_ascii=False))
assert s['report']==m['report']; print('STAGE report exactly matches material, stage=',s['stage'])
for k,v in s['journal'].items():
 if k=='selected_sources':
  for group in v:
   print('GROUP',{x:y for x,y in group.items() if x"'!='"'selected_sources'})
   for src in group['selected_sources']:
    expected=a['computed_evidence'] if src['source_id']==31 else i[src['path'][0]]
    assert src['value']==expected
    print('MATCHED SOURCE',json.dumps({x:y for x,y in src.items() if x"'!='"'value'},ensure_ascii=False))
 else: print('JOURNAL',k,json.dumps(v,ensure_ascii=False))
